add_action( 'wp_head', 'perfectpixel_smooth_scroll' );

function perfectpixel_smooth_scroll() {
	$offset = max( 0, (int) '{{smooth_scroll_offset}}' );
	// Pure CSS: works for every same-page link, no JavaScript needed.
	echo '<style>@media (prefers-reduced-motion: no-preference){html{scroll-behavior:smooth}}html{scroll-padding-top:' . (int) $offset . 'px}</style>' . "\n";
